-- User-requested removal; no CASCADE and no deletion of mechanics or progress.
alter table public.mechanics drop column if exists viability;

-- Generated by node scripts/catalog/generate.cjs; see docs/catalog-provenance.md.
insert into public.ranks (name, sort_order) values
('Bronze', 1),
('Silver', 2),
('Gold', 3),
('Platinum', 4),
('Diamond', 5),
('Champion', 6),
('Grand Champion I', 7),
('Grand Champion II', 8),
('Grand Champion III', 9),
('Supersonic Legend', 10)
on conflict (name) do nothing;

insert into public.mechanics (slug, name, description, category, difficulty, recommended_rank_id) values
('fast-aerial', 'Fast Aerial', 'The quickest standard way to gain vertical height: jump, tilt back, and use the second jump while boosting to accelerate upward.', 'movement', 2, (select id from public.ranks where name = 'Platinum')),
('ground-dribble', 'Ground Dribble', 'Carrying the ball on top of your car while driving on the ground. The foundation of all dribble and flick mechanics.', 'dribble', 2, (select id from public.ranks where name = 'Diamond')),
('air-dribble', 'Air Dribble', 'Carrying the ball through the air using boost and aerial control. The foundation of air-dribble-based mechanics.', 'air_dribble', 3, (select id from public.ranks where name = 'Champion')),
('half-flip', 'Half Flip', 'A recovery turn where you start a backflip, cancel it midway, then air roll to land facing the opposite direction with momentum.', 'movement', 2, (select id from public.ranks where name = 'Platinum')),
('speedflip', 'Speedflip', 'A tightly-timed diagonal front-flip cancel that keeps the car''s nose efficient and reaches max speed quickly, especially on kickoffs.', 'movement', 3, (select id from public.ranks where name = 'Champion')),
('wave-dash', 'Wavedash', 'A movement technique where you jump or land with a flip and let one or two wheels touch the ground, then flip into the direction of the wheels still off the ground to convert momentum.', 'movement', 1, (select id from public.ranks where name = 'Gold')),
('zap-dash', 'Zap Dash', 'A variant of the Wavedash, often executed from a landing, speedflip landing, jump, or wall transition. It involves allowing the two front wheels to touch the ground first. Immediately before the back wheels make contact, the player presses Jump. This action pops up the front of the car, enabling a forward wavedash using the subsequent flip input.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('180-dash', '180 Dash', 'A freestyle mechanic where a Wavedash is performed into the ground at a slight angle while holding Powerslide. The car lands on a single wheel, and precise aerial controls combined with a flip cancel allow for a controlled 180-degree turn on the ground.', 'dash', 2, (select id from public.ranks where name = 'Platinum')),
('360-dash', '360 Dash', 'A freestyle mechanic similar to the 180-Dash, but executed to achieve a full 360-degree turn on the ground.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('dash-flick', 'Dash Flick', 'A flick executed by performing a 180-Dash or 360-Dash maneuver directly beneath the ball. At the precise moment before completing the dash, the player releases the flip cancel, utilizing the stored momentum to pop the car off the ground. If timed correctly under the ball, this action powerfully launches the ball, typically forward.', 'dribble_flick', 2, (select id from public.ranks where name = 'Diamond')),
('double-dash', 'Double Dash', 'The execution of two consecutive Wavedashes without an additional jump input. This technique involves repeatedly initiating a Wavedash where the car''s opposite side "pops up," allowing for a rapid, chained series of dashes.', 'dash', 4, (select id from public.ranks where name = 'Grand Champion I')),
('haon-dash', 'Haon Dash', 'A technique initiated by jumping as if preparing for a Wavedash. Only one front wheel makes contact with the ground, followed by a flip to the side opposite the touching wheel. If timed correctly, this grants an additional flip and pops the car upward, allowing for a repeated chain of Haon Dashes.', 'dash', 4, (select id from public.ranks where name = 'Grand Champion II')),
('back-dashes', 'Back Dashes', 'Multiple backward wavedashes chained together to maintain backward momentum.', 'dash', 2, (select id from public.ranks where name = 'Diamond')),
('horse-dash', 'Horse Dash', 'A low-momentum Haon Dash variant. With minimal forward momentum and slight tilt, the player grounds a front wheel. A backward flip pops the front of the car up, which is immediately followed by a front flip to bring the nose down and pop the back wheels up. This sequence can be repeated.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('wall-dash', 'Wall Dash', 'Performing a Wavedash directly on a wall surface. This can be done in a controlled manner or by rapidly pressing jump and flip buttons while holding Powerslide to maintain control and forward momentum along the wall.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('curve-dash', 'Curve Dash', 'A Zap Dash performed while driving off the curved section of a wall, utilizing the momentum gained from the ramp-like transition.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('hel-jump-multi-dash', 'Hel Jump Multi Dash', 'An aerial setup where you land on both front wheels, jump to pop the nose up, and transition into an aerial using your flip.', 'movement', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('slingshot', 'Slingshot', 'A dribble shot where the ball is on the car. A 180-Dash or 360-Dash is initiated but not fully completed. Instead, the player allows the car to pop off the ground as described in the dash mechanics, launching the ball powerfully.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('short-dash', 'Short Dash', 'A celebratory or freestyle mechanic involving a "no-flip" (an instantly canceled flip to minimize flip motion). The car''s two front wheels make contact with the ground, creating a distinctive sliding motion across the surface.', 'dash', 2, (select id from public.ranks where name = 'Platinum')),
('astomo-wall-360-dash', 'Astomo/Wall 360 Dash', 'A freestyle mechanic. The player drives up a curved ramp at an angle. As the front wheels transition from the ramp to the wall, a jump is performed, immediately followed by a short dash on the wall. This causes the car to spin and, if Powerslide is held, slide along the wall, allowing for further controlled maneuvers.', 'dash', 4, (select id from public.ranks where name = 'Grand Champion I')),
('side-entry-dash', 'Side Entry Dash', 'A Wavedash performed in a sideways direction, typically initiated by a jump and then executed laterally.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('ceiling-dash', 'Ceiling Dash', 'A setup for a ceiling shot where the player jumps towards the ceiling, timing it to retain their flip upon contact. A Wavedash is then performed on the ceiling while holding Powerslide, allowing for a freestyle setup into a shot.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('reverse-ceiling-dash', 'Reverse Ceiling Dash', 'The Ceiling Dash mechanic executed in a backward direction.', 'dash', 3, (select id from public.ranks where name = 'Champion')),
('45-flick', '45 Flick', 'A flick performed while dribbling the ball. The player jumps, tilts the car approximately 45 degrees from the forward direction, and executes a diagonal flip to launch the ball.', 'dribble_flick', 2, (select id from public.ranks where name = 'Platinum')),
('athena-flick', 'Athena Flick', 'Any flick that results in the ball hitting the crossbar and missing the goal. This term was popularized by the YouTuber Athena.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('front-flip-flick', 'Front-Flip Flick', 'A flick performed while dribbling. The player jumps and executes a precisely timed front flip to flick or launch the ball towards the opponent''s goal.', 'dribble_flick', 2, (select id from public.ranks where name = 'Platinum')),
('90-flick', '90 Flick', 'A variant of the 45-Flick where the car is rotated 90 degrees from the forward direction before executing the diagonal flip.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('180-flick', '180 Flick', 'A flick where the car is rotated 180 degrees before executing the flip.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('turtle-flick', 'Turtle Flick', 'A unique flick performed while upside down on the ground (turtled). The player allows the ball to fall onto their car, then presses Jump. The game''s auto-righting mechanism briefly pops the car up and rotates it. If timed correctly with the ball''s impact, this action can flick or launch the ball upward and forward.', 'dribble_flick', 2, (select id from public.ranks where name = 'Diamond')),
('musty-flick', 'Musty Flick', 'A powerful flick that can be performed from a dribble or in the air. The player positions the car so its roof faces the ball, then executes an upside-down backward flip. For added power and style, the flip can be canceled and released later, utilizing stored momentum to launch the ball further. The player can then maintain aerial control or complete the flip.', 'dribble_flick', 4, (select id from public.ranks where name = 'Grand Champion I')),
('breezi-flick', 'Breezi Flick', 'A variation of the Musty Flick. The setup involves initiating a tornado spin (holding a left/right stick input while simultaneously holding standard Air Roll) until the car''s nose points upward. Immediately releasing Air Roll causes the car to spin with its nose pointing downward, at which point a Musty Flick is executed.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('jzr-flick', 'Jzr Flick', 'A very fast, powerful, and high-gaining variation of the 45-Flick. It typically launches the ball high against the opponent''s backboard, creating opportunities for a double tap.', 'dribble_flick', 4, (select id from public.ranks where name = 'Grand Champion II')),
('270-flick', '270 Flick', 'A flick where the car is rotated 270 degrees before executing the flip.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('180-wavedash-flick', '180 Wavedash Flick', 'A flick similar to a Slingshot. The player performs a 180-Wavedash and then immediately flicks the ball, typically with a back diagonal flip.', 'dribble_flick', 4, (select id from public.ranks where name = 'Grand Champion I')),
('mawzky-flick', 'Mawkzy Flick', 'A high-speed power-flick variant commonly associated with Mawkzy''s 1v1 style (often treated as an optimized 45-style flick execution).', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('slingshot-flick', 'Slingshot Flick', 'Using the slingshot momentum mechanic to generate a powerful flick with minimal setup.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('suffo-flick', 'Suffo Flick', 'A fake-flick sequence: jump away from the ball to sell a fake, then diagonal-backflip back into the ball to fire it unexpectedly.', 'dribble_flick', 4, (select id from public.ranks where name = 'Grand Champion II')),
('bismillah-flick', 'Bismillah Flick', 'A flick popularized by player Kevinnn. It involves a preflip into the ball, attempting to strike it with one of the front corners during a preflip cancel. Releasing the stick at the opportune moment causes the car to spin and powerfully launch the ball.', 'dribble_flick', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('cabbage-muncher', 'Cabbage Muncher', 'A mechanic where the player performs a normal or heli stall reset while dribbling the ball in the air. The momentum from the stall is then used to rotate back under the ball, allowing it to drop onto the car. This is followed by a pop reset to fling the ball away.', 'dribble_flick', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('classy-flick', 'Classy Flick', 'A deceptive, high-power, and versatile flick. It involves a jump, followed by a rapid tornado spin (Air Roll combined with steering) until the car is upside down, then a backflip. It is known for being relatively accessible for powerful, unexpected shots, particularly effective in 1v1 and 2v2 scenarios.', 'dribble_flick', 3, (select id from public.ranks where name = 'Champion')),
('windmill', 'Windmill', 'A freestyle mechanic where the car performs a tornado spin (typically backwards) and a jump input to follow the spin path, popping the ball up upon release of the air roll.', 'dribble_flick', 4, (select id from public.ranks where name = 'Grand Champion III')),
('360-windmill', '360 Windmill', 'A Windmill Flick executed to achieve a full 360-degree rotation of the car.', 'dribble_flick', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('flip-reset', 'Flip Reset', 'In the air, orienting the car''s wheels to touch the ball. When three or more wheels make contact, the player''s flip timer is reset, granting an unlimited second flip (dodge) in the air. Falling off the ball is preferred as jumping off activates the standard 1.5-second flip timer.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('arsenal-reset', 'Arsenal Reset', 'A flip reset approach where the player approaches the ball with the car''s nose pointing upward, often looking like a fake air dribble. The reset is typically achieved by pulling the stick back (nose towards the ceiling) before making contact, getting the reset on the side or slightly under the ball.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('pre-flip-reset', 'Pre-flip Reset', 'A setup technique where the player uses their flip before contacting the ball to orient the car for a perfect reset.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('ceiling-shot', 'Ceiling Shot', 'A shot setup where the player intentionally falls off the ceiling to gain a flip, which is then used to manipulate the ball towards the goal.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion I')),
('rapid-reset', 'Rapid Reset', 'A chained reset technique where the player executes a speedflip-like preflip into the ball while airborne to immediately obtain another flip reset.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('pop-reset', 'Pop Reset', 'A reset technique where the ball is set up like an air dribble. The player hits the ball with all four wheels slightly to the side or under its center, aiming to match the car''s velocity closely with the ball''s. Upon getting the reset, the flip is immediately used to pop the ball upward, allowing for continued control and potential chaining of pop resets.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('stall-reset', 'Stall Reset', 'Performing a stall (a mechanic that momentarily cancels vertical momentum) while airborne, allowing the ball to fall onto the car''s roof or body to obtain a flip reset.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion I')),
('heli-reset', 'Heli Reset', 'Similar to a Stall Reset, but performed with an added yaw spin of the car. This mechanic was discovered by the freestyler Gainner.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('maktuf-reset', 'Maktuf', 'An advanced freestyle reset technique. After obtaining an initial flip reset, the player immediately performs a backflip cancel combined with a directional air roll. This precise maneuver quickly reorients the car''s wheels to contact the ball again, allowing for aggressive, rapid chaining of multiple resets.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('360-maktuf', '360 Maktuf', 'A Maktuf Reset where the car rotates approximately 360 degrees after the initial reset and before obtaining the subsequent reset.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('pancake-reset', 'Pancake', 'A reset technique primarily executed on walls (and theoretically ceilings). The player approaches a ball rolling on or very close to the wall, jumps towards it, orientates their wheels, and "squishes" the ball against the wall to obtain a reset. This often effectively kills the ball''s momentum.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('wave-dash-reset', 'Wave-Dash Reset', 'Combining wavedash momentum with a flip reset - landing from the air and immediately getting another reset on contact.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('arsenal-dash-reset', 'Arsenal Dash Reset', 'A specialized flip-reset technique popularized by Arsenal. It involves approaching the ball from the front or slightly to the side with the car''s nose pointing upward (an ''Arsenal Reset'' approach), then using the ball as a surface to perform a Wavedash-like maneuver. Two wheels make contact, and a quick, canceled flip grants an immediate new jump.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('murie-reset', 'Murie Reset', 'A reset technique where, after obtaining a flip reset, the player tilts their car backward (nose pointing upward, wheels towards the camera). A backflip is then executed and canceled, allowing the ball to fall onto the car for another reset.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('front-flip-reset', 'Front-flip Reset', 'Performing a front flip into a position that immediately grants a flip reset.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('side-flip-reset', 'Side-Flip Reset', 'A flip reset using a side-flip to approach the ball from sideways orientation, creating unique angles.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('jerry-reset', 'Jerry Reset', 'A stylish freestyle reset technique that combines a flip reset with a Wavedash against the ball. This allows the car to rebound off the ball in a way that immediately positions it for another move (e.g., a backflip or Musty Flick), often used for extremely fast chained resets.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('jump-reset', 'Jump Reset', 'A general term often used synonymously with Flip Reset. It refers to the moment when all four wheels of the car simultaneously touch the ball, causing the game to register it as a solid surface. This resets the player''s jump timer, allowing them to retain their second jump (dodge/flip) indefinitely until it is used or they touch the ground.', 'flip_reset', 3, (select id from public.ranks where name = 'Champion')),
('tko-reset', 'TKO Reset', 'A reset technique involving a speedflip preflip into the ball. Instead of immediately getting the reset like a Rapid Reset, the player achieves a slight initial touch, continues rotating the car, and then obtains the reset slightly later by rotating back under the ball and correctly orienting the wheels.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('purple-shot', 'Purple Shot', 'A powerful shot, initially exclusive to Rocket League Sideswipe and later discovered in the main game. It involves an Arsenal Reset-like setup but with a specific flip execution that causes the ball to pop away from the car with immense power. The player retains their flip and control, allowing for backboard plays or ground flicks.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('evample-reset', 'Evample Reset', 'A reset technique initiated from the wall with the ball. The player quickly maneuvers above the ball, then performs a flat stall at a specific time to move towards the ball and obtain a reset from its top or top-side surface.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('musty-reset', 'Musty Reset', 'A technique where a Musty Flick motion is performed off of a ball that provides a reset, but instead of fully launching the ball, the player doesn''t cancel the flick and uses the generated momentum to secure a flip reset.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('henko-reset', 'Henko Reset', 'A precise, mechanically clean flip reset variant known for its tight execution and consistency. Popularized by Henko.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('squishy-reset', 'Squishy Reset', 'A smooth flip reset using fluid air roll movements that make the technique appear effortless. Associated with SquishyMuffinz.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('shay-reset', 'Shay Reset', 'A challenging freestyle mechanic. Immediately after obtaining a flip reset, the player rotates their car away from the ball, orienting the nose sideways relative to the ball. A backward diagonal flip is then executed into the ball to achieve another reset.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('jakze-reset', 'Jakze Reset', 'An upside-down front flip that is immediately flip-canceled into the bottom-right or bottom-left, depending on the car''s initial tilt during the front flip. If the wheels are tilted left, a down-right flip cancel is used; if tilted right, a down-left flip cancel is used.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('reverse-jakze-reset', 'Reverse-Jakze Reset', 'A Jakze-style reset performed from an inverted/upside-down approach angle. Named after Jakze.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('ground-dash-reset', 'Ground-Dash Reset', 'Using a ground dash to pop the ball upward, then getting an aerial flip reset in one continuous motion.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('lix-jump', 'Lix Jump', 'A specific jump where the player drives at the wall at an angle. As the front wheels reach the top of the curved ramp, a single jump is performed, popping them up. At the correct moment, a flip is used to perform a wavedash back towards the wall, but in a manner that pops the car off the wall while retaining a flip.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('car-reset', 'Car Reset', 'Obtaining a flip reset by making contact with a teammate''s or opponent''s car. This is primarily a freestyle mechanic and is difficult to execute reliably in competitive play.', 'flip_reset', 3, (select id from public.ranks where name = 'Champion')),
('murie-pop', 'Murie Pop', 'A unique mechanic where the car and ball land on the ground simultaneously. The ball makes a slight contact with the car''s nose, and the ball''s bounce causes the car''s front wheels to bounce sufficiently high to allow the player to initiate an aerial maneuver with a retained flip.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('hel-jump', 'Hel Jump', 'A mechanic where the player points the car''s front wheels into the ground, performs a single jump, and allows the front wheels to pop back up after the back wheels touch down from the jump. This motion propels the car in that direction, enabling an aerial launch from the ground.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion I')),
('turtle-reset', 'Turtle Reset', 'Obtaining a flip reset on the ball while the car is positioned on its roof on the ground.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('backflip-cancel-reset', 'Backflip Cancel', 'Executing a backflip that is immediately flip-canceled to achieve a reset.', 'flip_reset', 3, (select id from public.ranks where name = 'Champion')),
('frontflip-cancel-reset', 'Frontflip Cancel', 'Using a frontflip cancel to adjust your position for an easier flip reset angle.', 'flip_reset', 3, (select id from public.ranks where name = 'Champion')),
('murie-cancel', 'Murie Cancel', 'A flip cancel technique used in combination with Murie''s reset style for precise ball positioning and follow-up options. Named after Murie.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('amalix-jump', 'Amalix Jump', 'Synonym for Lix Jump, also known as Fetelix Jump or Fetelix Reset.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('spam-blitz-dash-reset', 'Spam/Blitz Dash Reset', 'Rapidly chaining dash flicks and flip resets in quick succession for unpredictable, spammy offensive pressure.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('hyd-reset', 'HYD Reset', 'An Arsenal Reset setup where the car''s path is mimicked. The player leans back slightly before contact and holds directional air roll at contact. Timing is crucial, and catching the ball with the bottom half of the car typically allows for greater ball control and less pop compared to a standard Arsenal Reset.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('ceiling-shuffle', 'Ceiling Shuffle', 'A freestyle mechanic where the car performs a "wiggle" motion on the ceiling without constant drive input, using specific physics (wheel stickiness) to repeatedly fall off the ceiling partially from one side then the other. This allows the car to remain on the ceiling for extended periods. A reverse ceiling shuffle is performed backward.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion II')),
('reverse-ceiling-shuffle', 'Reverse Ceiling Shuffle', 'A ceiling shuffle performed while moving backward, making the approach harder to read.', 'flip_reset', 4, (select id from public.ranks where name = 'Grand Champion III')),
('osuea-reset', 'Osuea Reset', 'A technical flip reset with unique air roll patterns for difficult angles. Named after Osuea.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('backwards-jerry-reset', 'Backwards Jerry Reset', 'A Jerry Reset performed in reverse.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('reverse-pancake-reset', 'Reverse Pancake Reset', 'A Pancake Reset where the car''s nose points downward or sideways instead of upward during the contact.', 'flip_reset', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('pogo', 'Pogo', 'A mechanic where the car and ball fall towards the ground. The player attempts to match the ball''s speed, slightly accelerating at the end, then allows one of the car''s front or back corners to hit the ground simultaneously with the ball''s bounce. If performed correctly, this pops the car back up, allowing the player to continue their shot.', 'pogo', 3, (select id from public.ranks where name = 'Champion')),
('ceiling-pogo', 'Ceiling Pogo', 'A Pogo performed off the ceiling surface.', 'pogo', 4, (select id from public.ranks where name = 'Grand Champion I')),
('reverse-pogo', 'Reverse Pogo', 'A Pogo executed using one of the car''s back corners.', 'pogo', 3, (select id from public.ranks where name = 'Champion')),
('flingshot', 'Flingshot', 'A redirect shot where the player dribbles the ball along a wall, performs a Pogo off the ramp, and catches the ball at the precise moment it bounces. This allows the ball to launch off one corner of the car with immense power.', 'pogo', 4, (select id from public.ranks where name = 'Grand Champion I')),
('kuxir-pinch', 'Kuxir Pinch', 'A powerful pinch where the ball is compressed between the car and a sidewall, typically near the player''s own back corner. This generates extreme velocity for the ball.', 'pinch', 3, (select id from public.ranks where name = 'Champion')),
('ground-pinch', 'Ground Pinch', 'A pinch where the ball is compressed between the car and the ground.', 'pinch', 3, (select id from public.ranks where name = 'Champion')),
('team-pinch', 'Team Pinch', 'A pinch performed by two players simultaneously contacting the ball, without necessarily involving environmental surfaces.', 'pinch', 3, (select id from public.ranks where name = 'Champion')),
('team-groundpinch', 'Team Groundpinch', 'A team pinch executed on the ground, with both cars sandwiching the ball against the floor.', 'pinch', 3, (select id from public.ranks where name = 'Champion')),
('team-ceiling-pinch', 'Team Ceiling Pinch', 'Similar to a Team Ground Pinch, but executed on the ceiling.', 'pinch', 4, (select id from public.ranks where name = 'Grand Champion I')),
('team-astral-pinch', 'Team Astral Pinch', 'An advanced team pinch that sends the ball in an unexpected, ''astral'' trajectory. High skill and coordination required.', 'pinch', 4, (select id from public.ranks where name = 'Grand Champion III')),
('astral-pinch', 'Astral Pinch', 'A pinch executed from the opponent''s corner directly towards the goal. This extremely difficult shot requires precise trajectory and is challenging to save.', 'pinch', 4, (select id from public.ranks where name = 'Grand Champion II')),
('ceiling-pinch', 'Ceiling Pinch', 'Pinching the ball against the ceiling to create a powerful downward shot that''s hard to read.', 'pinch', 3, (select id from public.ranks where name = 'Champion')),
('bbl-pinch', 'BBL Pinch', 'A pinch, similar to a Kuxir Pinch, but executed using the backside of the car instead of the front. This technique was popularized by Arsenal.', 'pinch', 3, (select id from public.ranks where name = 'Champion')),
('post-pinch', 'Post Pinch', 'Pinching the ball against the goal post to create an unexpected rebound or shot on net.', 'pinch', 2, (select id from public.ranks where name = 'Diamond')),
('sidewall-redirect', 'Sidewall Redirect', 'A redirect or shot aimed into one of the sidewalls, followed by a read of the ball''s bounce and a subsequent redirect towards the goal. Also known as a Sidewall Read.', 'redirect', 3, (select id from public.ranks where name = 'Champion')),
('corner-read', 'Corner Read', 'Similar to a Sidewall Redirect, but the ball is hit into the opponent''s corner, and its bounce is read for a subsequent redirect towards the goal.', 'redirect', 3, (select id from public.ranks where name = 'Champion')),
('psycho', 'Psycho', 'A redirect where the player intentionally hits the ball into their own backboard (using various methods like a direct hit, ground pinch, or Musty Flick), then reads the rebound and redirects the ball across the entire field into the opponent''s goal. This mechanic was popularized by the player Owen Williams, known as Psycho.', 'redirect', 4, (select id from public.ranks where name = 'Grand Champion II')),
('corner-psycho', 'Corner Psycho', 'A Psycho redirect performed from the player''s own corner instead of the backboard.', 'redirect', 4, (select id from public.ranks where name = 'Grand Champion III')),
('groundpinch-psycho', 'Groundpinch Psycho', 'Combining a ground pinch with a psycho redirect, creating a unique and highly unpredictable shot.', 'redirect', 4, (select id from public.ranks where name = 'Grand Champion III')),
('musty-psycho', 'Musty Psycho', 'A psycho redirect executed with a musty flick motion, combining two iconic mechanics into one.', 'redirect', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('double-touch', 'Double Tap', 'Hitting the ball off the backboard and then immediately scoring the rebound before touching the ground.', 'shot', 3, (select id from public.ranks where name = 'Champion')),
('triple-tap', 'Triple Tap', 'A double tap with an extra touch — hitting the ball off the backboard, catching it in the air, and scoring on the second or third rebound.', 'shot', 4, (select id from public.ranks where name = 'Grand Champion I')),
('ceiling-double', 'Ceiling Double', 'A double tap executed from a ceiling shot setup, combining ceiling mechanics with backboard reads.', 'shot', 3, (select id from public.ranks where name = 'Champion')),
('ground-double', 'Ground Double', 'A double tap that starts from the ground, typically requiring a high pop and quick aerial.', 'shot', 3, (select id from public.ranks where name = 'Champion')),
('redirect', 'Redirect (from pass)', 'Redirecting a pass from a teammate on net. A fundamental team-play mechanic that requires good positioning and timing.', 'redirect', 2, (select id from public.ranks where name = 'Diamond')),
('squishy-save', 'Squishy Save', 'A defensive maneuver where a player drives into their own goal, continues up the back wall, and emerges from the ceiling of the goal with a flip, positioning themselves to make a save.', 'save', 3, (select id from public.ranks where name = 'Champion')),
('zen-touch', 'Zen Touch', 'A precise and controlled touch on a fast-moving ball, allowing for exceptional control and manipulation. This technique enables a player to "catch" and control a ball that is traveling at high speed.', 'save', 5, (select id from public.ranks where name = 'Supersonic Legend')),
('two-wheel-drift', 'Two Wheel Drift', 'Driving on two wheels while dribbling the ball, used for style and to show extreme car control.', 'dribble', 2, (select id from public.ranks where name = 'Diamond')),
('360-dribble', '360° Dribble', 'Rotating the car 360 degrees while maintaining a ground dribble, demonstrating exceptional ball control.', 'dribble', 2, (select id from public.ranks where name = 'Diamond')),
('reverse-musty', 'Reverse Musty', 'A musty flick performed backward, sending the ball in the opposite direction of a standard musty.', 'dribble_flick', 4, (select id from public.ranks where name = 'Grand Champion I')),
('wall-pinch', 'Wall Pinch', 'Pinching the ball between your car and a wall to launch it at high velocity.', 'pinch', 4, (select id from public.ranks where name = 'Diamond')),
('shadow-defense', 'Shadow Defense', 'Retreating between the ball and your goal without committing, maintaining pressure while forcing the opponent to make the first move.', 'save', 1, (select id from public.ranks where name = 'Silver')),
('aerial-save', 'Aerial Save', 'Using an aerial to reach and deflect a ball that would otherwise be an unstoppable shot on goal.', 'save', 2, (select id from public.ranks where name = 'Silver')),
('power-shot', 'Power Shot', 'A hard, well-angled ground shot with maximum boost and car speed to overpower the goalkeeper.', 'powershot', 1, (select id from public.ranks where name = 'Bronze')),
('aerial-redirect', 'Aerial Redirect', 'Hitting a teammate''s or rebounding ball mid-air to change its direction toward the goal.', 'redirect', 3, (select id from public.ranks where name = 'Platinum')),
('boost-management', 'Boost Management', 'The discipline of collecting boost pads efficiently, never going empty, and denying large pads from opponents.', 'movement', 1, (select id from public.ranks where name = 'Bronze')),
('rotation', 'Proper Rotation', 'Going back post when teammates are on offence, cutting off angles, and maintaining a 3-man rotation in team modes.', 'movement', 1, (select id from public.ranks where name = 'Bronze')),
('demos', 'Demolitions', 'Using supersonic speed to destroy opponents'' cars, disrupting defense or clearing the field for a shot.', 'movement', 1, (select id from public.ranks where name = 'Silver'))
on conflict (slug) do update set name = excluded.name, description = excluded.description,
category = excluded.category, difficulty = excluded.difficulty, recommended_rank_id = excluded.recommended_rank_id;

